// Маскировка контактов ДО регулярок и модели. Правила — gold_sample.MASK_RULES (та же функция маскировала эталон),
// сюда приходят из узла «Настройки» (mask_json; перевод Python -> JS и обновление — eval_extraction.py --sync-workflow).
const cfg = $('Настройки').first().json;
const M = JSON.parse(cfg.models_json);
const MASKS = JSON.parse(cfg.mask_json).map(([src, flags, label, keep]) => [new RegExp(src, 'gu' + flags), label, keep]);
// страховка к промпту: явная попытка управлять моделью из текста объявления
const INJECTION = /игнорир\S*\s+(?:все\s+)?(?:предыдущ|правил|инструкц)|ignore\s+(?:all\s+)?previous|(?:модель|нейросеть|бот|ии)[,:]?\s+(?:отметь|пометь|напиши|ответь)/i;
const mask = (t) => MASKS.reduce(
  (s, [rx, label, keep]) => s.replace(rx, (...g) => (keep ? g[1] + ' ' : '') + label), String(t || ''));

return $input.all().map((it, i) => {
  const text = mask(it.json.text);
  const posted = it.json.posted_at ? new Date(it.json.posted_at).toISOString().slice(0, 10) : 'неизвестна';
  const source = it.json.source || 'неизвестен';
  // источник и дата — отдельными строками вне «««…»»», текст объявления не смешивается с метаданными
  const user = cfg.user_template.replace('{source}', () => source).replace('{posted}', () => posted)
    .replace('{text}', () => text);
  return {
    json: {
      post_id: String(it.json.post_id), source, posted, text_masked: text,
      suspect_injection: INJECTION.test(text), started_at: Date.now(),
      request: {
        model: M.primary, temperature: M.temperature, max_tokens: M.max_tokens,
        response_format: { type: 'json_object' }, usage: { include: true },
        messages: [{ role: 'system', content: cfg.system_prompt }, { role: 'user', content: user }],
      },
    },
    pairedItem: { item: i },
  };
});

// Регулярки: карточка без языковой модели — зеркало baseline_card() из eval_extraction.py (разбор шаблона — как
// tg_merge.parse_post). Сами выражения не переписаны вручную: их источники приходят из узла «Настройки» (regex_json;
// перевод Python -> JS — eval_extraction.js_regex(), обновление — --sync-workflow). Паритет с Python — на эталоне.
const cfg = $('Настройки').first().json;
const RX = JSON.parse(cfg.regex_json);
const C = {};
const rx = (k, g = '') => C[k + g] || (C[k + g] = new RegExp(RX[k][0], RX[k][1] + 'u' + g));
const find = (k, s) => rx(k).exec(s);
const SP = '[\\t\\n\\x0b\\x0c\\r\\x1c-\\x1f \\x85\\xa0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000]+';
const STRIP = new RegExp(`^${SP}|${SP}$`, 'gu');
const strip = (s) => s.replace(STRIP, '');                                   // str.strip() Python
const head = (s, n) => Array.from(s).slice(0, n).join('');                    // s[:n] Python — по символам
const pyRound = (x) => { const f = Math.floor(x), d = x - f; return d > 0.5 || (d === 0.5 && f % 2 !== 0) ? f + 1 : f; };
const quote = (m, s, low) => (m ? head(strip(s.length === low.length ? s.slice(m.index, m.index + m[0].length) : m[0]), 200) || null : null);
const ROOMS = { 'студия': 'студия', '1-к': '1', '2-к': '2' };
const FLAG_RX = [['предоплата_без_просмотра', 'flag_prepay'], ['уход_в_другой_мессенджер', 'flag_messenger'],
  ['инструкция_модели_в_тексте', 'flag_injection']];
const UTIL_QUOTE = { 'включена': ['KU_INCL'], 'сумма': ['KU_AFTER', 'KU_BEFORE'],
  'счётчики сверху': ['EXCEPT_METERS', 'METERS', 'KU_ON_TOP', 'KU_INCL'] };

// --- tg_merge: field, parse_price, parse_rooms, parse_post (только поля карточки)
const field = (t, e) => { const m = new RegExp(e + RX.tg_field[0], 'u').exec(t); return m ? strip(m[1]) : null; };
function parsePrice(s) {
  if (!s) return null;
  const m = find('tg_price', s.toLowerCase().replace(/\xa0/g, ' '));
  if (!m) return null;
  let v = parseFloat(m[1].replace(rx('tg_price_sep', 'g'), ''));
  if (m[2] && v < 1000) v *= 1000;
  return v >= 5000 && v <= 500000 ? v : null;
}
function parseRooms(s) {
  s = (s || '').toLowerCase();
  if (s.includes('студ')) return 'студия';
  const m = find('tg_rooms', s);
  return m ? `${m[1]}-к` : null;
}
function parsePost(t) {
  const a = find('tg_area', field(t, '📐') || t);
  const kind = (field(t, '🛋') || '').toLowerCase();
  const metro = field(t, '🚇') || (find('tg_metro', t) || [null, null])[1];
  const addr = field(t, '📍');
  const start = find('tg_start', field(t, '📆') || '');
  const lease = (field(t, '⏱') || '').toLowerCase();
  return {
    object: kind.includes('комнат') && !kind.includes('комнатн') ? 'комната' : kind.includes('дом') ? 'дом' : 'квартира',
    fmt: parseRooms(field(t, '👉') || (kind ? '' : head(t, 200))),
    area: a ? parseFloat(a[1].replace(/,/g, '.')) : null,
    price: parsePrice(field(t, '💰')),
