// --- eval_extraction: to_rub, util_from_text, baseline_card
const toRub = (v) => {
  const x = find('rub_thousands', v) ? parseFloat(v.replace(rx('rub_sep', 'g'), '')) : parseFloat(v.replace(/,/g, '.'));
  return x < 100 ? x * 1000 : x;
};
function utilFromText(t) {
  if (typeof t !== 'string' || !t) return ['не указано', null];
  if (find('KU_INCL', t)) return [find('METERS', t) || find('EXCEPT_METERS', t) ? 'счётчики сверху' : 'включена', null];
  for (const k of ['KU_AFTER', 'KU_BEFORE']) {
    for (const m of t.matchAll(rx(k, 'g'))) {
      const vals = [toRub(m[1])].concat(m[3] ? [toRub(m[3])] : []);
      if (vals.every((v) => v >= 300 && v <= 30000)) return ['сумма', pyRound(vals.reduce((a, b) => a + b, 0) / vals.length)];
    }
  }
  return [find('METERS', t) || find('KU_ON_TOP', t) ? 'счётчики сверху' : 'не указано', null];
}
function baselineCard(text) {
  const p = parsePost('#спб\n' + text);
  const low = text.toLowerCase();
  const mDaily = find('daily', low), daily = !!mDaily;
  let price = null, evPrice = null;
  if (!daily && p.price) { price = p.price; evPrice = field(text, '💰'); }
  else if (!daily) {
    const src = field(text, '💸');
    const mc = src ? null : find('price_ctx', low);
    price = parsePrice(src || (mc ? mc[1] : null));
    evPrice = src || quote(mc, text, low);
  }
