  const floor = fl ? parseInt(fl[1] || fl[3] || fl[5] || fl[6], 10) : null;
  const floors = fl && (fl[2] || fl[4]) ? parseInt(fl[2] || fl[4], 10) : null;
  const walk = find('walk', low);
