  else if ((mCom = find('com_sum', low))) { comSt = 'сумма'; comRub = Math.trunc(toRub(mCom[1])); }
  let depSt = 'не указано', depRub = null;
  if ((mDep = find('dep_none', low))) depSt = 'нет';
  else if ((mDep = find('dep_sum', low))) { depSt = 'сумма'; depRub = Math.trunc(toRub(mDep[1])); }
  const fmt = p.fmt;
  const rooms = ROOMS[fmt] || (fmt && /^[0-9]/.test(fmt) && parseInt(fmt[0], 10) >= 3 ? '3+' : null);
  const flags = FLAG_RX.filter(([, k]) => find(k, text)).map(([f]) => f);
  const isOffer = !find('seeker', low);
  if (isOffer && !price && !daily) flags.push('нет_цены');
  const street = (p.address && strip(p.address.replace(rx('street_tail', 'g'), ''))) || null;
  const months = find('months', low);
  const mLong = months ? null : find('long_words', low);
  const iUntil = text.indexOf('📆 до');
  let deal = 'unknown', evDeal = null;
  if (daily) { deal = 'daily'; evDeal = quote(mDaily, text, low); }
  else if (iUntil >= 0) { deal = 'short'; evDeal = head(strip(text.slice(iUntil).split('\n')[0]), 200); }
  else if (p.lease === 'длительно' || p.lease === 'коротко') { deal = p.lease === 'длительно' ? 'long' : 'short'; evDeal = field(text, '⏱'); }
  else if (months) { deal = parseInt(months[1], 10) >= 11 ? 'long' : 'short'; evDeal = quote(months, text, low); }
  else if (mLong) { deal = 'long'; evDeal = quote(mLong, text, low); }
  let kind;
  if (find('apart', low)) kind = 'апартаменты';
  else if (text.includes('🛋')) kind = { 'квартира': 'квартира', 'комната': 'комната', 'дом': 'другое' }[p.object] || 'unknown';
  else kind = find('room_word', low) && !find('rooms_adj', low) ? 'комната' : (p.area || floor) ? 'квартира' : 'unknown';
  const qCom = quote(mCom, text, low), qDep = quote(mDep, text, low);
  const lowAr = low.replace(rx('ar_neg', 'g'), (m) => ' '.repeat(m.length));
  let role = 'неизвестно', qRole = null, mAr;
  if (isOffer) {
    if ((mAr = find('ar_realtor', lowAr) || find('ar_an', text))) { role = 'риэлтор'; qRole = quote(mAr, text, low); }
    else if (comSt === 'сумма' || comSt === 'процент') { role = 'риэлтор'; qRole = qCom; }
    else if ((mAr = find('ar_owner', low))) { role = 'собственник'; qRole = quote(mAr, text, low); }
  }
  const ev = { price_rub: price ? evPrice : null, deal: evDeal, utilities_status: evUtil, utilities_rub: utilRub ? evUtil : null,
    commission_status: qCom, commission_pct: comPct ? qCom : null, commission_rub: comRub ? qCom : null,
    deposit_status: qDep, deposit_rub: depRub ? qDep : null, author_role: qRole };
  return {
    is_offer: isOffer, is_closed: !!find('closed', low), deal, kind, rooms, area_m2: p.area, floor, floors,
    price_rub: price ? Math.trunc(price) : null, utilities_status: util, utilities_rub: utilRub,
    commission_status: comSt, commission_rub: comRub, commission_pct: comPct, deposit_status: depSt, deposit_rub: depRub,
    metro: p.metro_tg, metro_walk_min: walk ? parseInt(walk[1] || walk[2], 10) : null, street, move_from: p.move_from,
    red_flags: flags, author_role: role, evidence: Object.fromEntries(Object.entries(ev).filter(([, v]) => typeof v === 'string' && v)),
  };
}

