else {
  const key = Object.keys(M.prices_per_1m_usd).find((k) => String(usedModel).startsWith(k)) || M.primary;
  const [pin, pout] = M.prices_per_1m_usd[key];
  cost = (tin * pin + tout * pout) / 1e6;
}
cost = Math.round(cost * (1 + M.or_fee) * 1e8) / 1e8;   // + комиссия OpenRouter при пополнении баланса
return {
