    post_id: src.post_id, text_masked: src.text_masked, card,
    is_closed: !!(card && card.is_closed),            // «СДАНА» — в статистику цен, не в выдачу
    route: status === 'ok' ? 'card' : 'hitl', status, errors,
    model: usedModel, extractor: fallbackUsed ? 'kimi' : 'deepseek', fallback_used: fallbackUsed, tokens_in: tin, tokens_out: tout, cost_usd: cost,
    latency_ms: Date.now() - src.started_at,
  },
};
